import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS, T, en, fin, DUR, Textura, Profundidad, Brillo, Paso, Chip, Contador, Entrar, Ondas, Etiqueta, Recorrido, tono, h, golpe, interpolate, clamp, Easing, FONT} from './kit';

// DINERO 2026-11-21 09:00 — El paquete grande no siempre sale más barato.
// Protagonista que viaja: los dos frascos de mantequilla de maní (grande y pequeño). Paleta: blanco de pasillo -> rojo cuando el grande pierde -> dorado en la etiqueta -> blanco.
export const SUBS = {arriba: 230, acento: '#FFC83D'};
const ROJO = '#FF4D4D', ORO = '#FFC83D', BLANCO = '#EEF2F4';
// inicio de cada escena (E1 .. E8) = primera palabra de su frase
const E = [T(0), T(8), T(28), T(43), T(61), T(78), T(105), T(127)];
export const CORTES = E.slice(1).map((t) => t - 0.1);

type Ease = (x: number) => number;
const K = (s: number, k: [number, number][], ease: Ease = Easing.inOut(Easing.cubic)) => interpolate(s, k.map((a) => a[0]), k.map((a) => a[1]), {...clamp, easing: ease});
const f1 = (n: number) => n.toFixed(1);
const PIEL: Record<string, string> = {pielO: '#7a4e33', pielC: '#e5b690', pielM: '#c58d64'};

/* ---------- degradados compartidos ---------- */
