    <linearGradient id="lidC" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stopColor="#1d3f73" /><stop offset=".35" stopColor="#4684d6" /><stop offset=".6" stopColor="#2f66b4" /><stop offset="1" stopColor="#173461" /></linearGradient>
    <linearGradient id="labC" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#fffaf0" /><stop offset="1" stopColor="#efd9ae" /></linearGradient>
    <linearGradient id="pielO" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#9a6845" /><stop offset="1" stopColor="#5c3822" /></linearGradient>
    <linearGradient id="pielC" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#f3cfae" /><stop offset="1" stopColor="#cf9a72" /></linearGradient>
    <linearGradient id="pielM" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#dca97f" /><stop offset="1" stopColor="#b17850" /></linearGradient>
