    <linearGradient id="manTeal" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#38b8aa" /><stop offset="1" stopColor="#15625c" /></linearGradient>
    <linearGradient id="manMost" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#e6b043" /><stop offset="1" stopColor="#a4701a" /></linearGradient>
    <linearGradient id="bill" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#b6dfa0" /><stop offset="1" stopColor="#5f9d55" /></linearGradient>
    <linearGradient id="metal" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#f1f4f6" /><stop offset=".5" stopColor="#b6c0c8" /><stop offset="1" stopColor="#8a959e" /></linearGradient>
    <linearGradient id="madera" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#f1e8d6" /><stop offset="1" stopColor="#c0b38f" /></linearGradient>
    <linearGradient id="suelo" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#f2f5f7" /><stop offset="1" stopColor="#b3bfc8" /></linearGradient>
    <linearGradient id="oceano" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#4a93c6" /><stop offset="1" stopColor="#1d4f7b" /></linearGradient>
    <radialGradient id="aureOro"><stop offset="0" stopColor="#FFC83D" stopOpacity=".8" /><stop offset="1" stopColor="#FFC83D" stopOpacity="0" /></radialGradient>
    <radialGradient id="aureRojo"><stop offset="0" stopColor="#FF4D4D" stopOpacity=".7" /><stop offset="1" stopColor="#FF4D4D" stopOpacity="0" /></radialGradient>
    <radialGradient id="esfera" cx=".35" cy=".3" r=".85"><stop offset="0" stopColor="#fff" stopOpacity=".38" /><stop offset=".55" stopColor="#fff" stopOpacity="0" /><stop offset="1" stopColor="#001a33" stopOpacity=".55" /></radialGradient>
  </defs>
);

const Bill = () => (
  <g>
    <rect x={-70} y={-34} width={140} height={68} rx={7} fill="url(#bill)" stroke="#467a3e" strokeWidth={3} />
    <rect x={-60} y={-25} width={120} height={50} rx={4} fill="none" stroke="#e9f6df" strokeWidth={2} opacity={0.7} />
    <circle r={21} fill="#c4e6ae" stroke="#467a3e" strokeWidth={2.5} />
