/* ---------- el frasco (protagonista) ---------- */
const Frasco: React.FC<{x: number; y: number; e?: number; rot?: number; sx?: number; sy?: number; rojo?: number; grieta?: number; unidad?: number; oro?: number; gris?: number; w?: number; kg?: string}> = ({x, y, e = 1, rot = 0, sx = 1, sy = 1, rojo = 0, grieta = 0, unidad = 0, oro = 0, gris = 0, w = 0, kg = ''}) => (
  <g transform={`translate(${f1(x)} ${f1(y)}) rotate(${f1(rot)}) scale(${(e * sx).toFixed(3)} ${(e * sy).toFixed(3)})`}>
    {oro > 0 && <ellipse cx={0} cy={-30} rx={230} ry={290} fill="url(#aureOro)" opacity={oro} />}
    {rojo > 0 && <ellipse cx={0} cy={-30} rx={230} ry={290} fill="url(#aureRojo)" opacity={rojo * 0.8} />}
    <rect x={-105} y={-150} width={210} height={290} rx={44} fill="url(#pbC)" />
    <rect x={-92} y={-132} width={22} height={236} rx={11} fill="#fff" opacity={0.28} />
    <rect x={78} y={-120} width={10} height={200} rx={5} fill="#fff" opacity={0.12} />
    <rect x={-100} y={-62} width={200} height={158} rx={14} fill="url(#labC)" stroke="#d8b878" strokeWidth={3} />
    <path d="M-100 -48 a14 14 0 0 1 14 -14 H86 a14 14 0 0 1 14 14 V-28 H-100Z" fill="#e8892b" />
    <circle cx={-14} cy={4} r={24} fill="#d19a52" stroke="#a8742f" strokeWidth={3} />
    <circle cx={14} cy={20} r={20} fill="#d9a65e" stroke="#a8742f" strokeWidth={3} />
    <rect x={-72} y={-48} width={90} height={8} rx={4} fill="#fff4dc" opacity={0.9} />
    <rect x={-70} y={46} width={140} height={6} rx={3} fill="#c9b48a" />
    {kg !== '' && <g><rect x={-86} y={62} width={172} height={32} rx={7} fill={unidad > 0.5 ? ORO : '#3a3f45'} />
    <text x={0} y={86} textAnchor="middle" fontSize={23} fontWeight={800} fontFamily={FONT} fill={unidad > 0.5 ? '#2a1c08' : '#e9edf0'}>{kg}</text></g>}
    <rect x={-92} y={-176} width={184} height={34} rx={8} fill="url(#pbC)" />
    <rect x={-100} y={-236} width={200} height={70} rx={16} fill="url(#lidC)" />
    {[-70, -40, -10, 20, 50, 80].map((lx) => <rect key={lx} x={lx} y={-228} width={8} height={54} rx={4} fill="#fff" opacity={0.12} />)}
    <rect x={-86} y={-226} width={26} height={12} rx={6} fill="#fff" opacity={0.35} />
    {rojo > 0 && <rect x={-105} y={-150} width={210} height={290} rx={44} fill={ROJO} opacity={rojo * 0.5} />}
    {rojo > 0 && <rect x={-105} y={-150} width={210} height={290} rx={44} fill="none" stroke={ROJO} strokeWidth={8} opacity={rojo} />}
    {gris > 0 && <rect x={-105} y={-236} width={210} height={376} rx={30} fill="#aab4bb" opacity={gris * 0.62} />}
    {grieta > 0 && (
      <g opacity={Math.min(1, grieta * 2)}>
        <path d="M62 -150 L46 -118 L70 -100 L50 -74 L66 -50 L86 -78 L66 -104 L88 -128 L82 -150Z" fill="#2b1507" stroke="#fff3d6" strokeWidth={3} />
        <g transform={`translate(${74 + Math.sin(w * 3) * 3} -128) rotate(${-34 + Math.sin(w * 2.1) * 6}) scale(.6)`}><Bill /></g>
        <g transform={`translate(66 -114) rotate(${-62 + Math.sin(w * 2.7) * 5}) scale(.54)`}><Bill /></g>
      </g>
    )}
  </g>
);

/* ---------- brazo 2D: hombro -> codo -> mano, grosor que se afina, manga del color de la ropa ---------- */
const Brazo: React.FC<{sx: number; sy: number; hx: number; hy: number; piel: string; manga: string; lado?: number; g?: number; curl?: number}> = ({sx, sy, hx, hy, piel, manga, lado = 1, g = 1.5, curl = 0.5}) => {
  const dx = hx - sx, dy = hy - sy, d = Math.max(1, Math.hypot(dx, dy));
  const Lg = Math.max(d * 0.56, 330 * g);
  const hh = Math.sqrt(Math.max(0, Lg * Lg - (d / 2) * (d / 2)));
  const ex = (sx + hx) / 2 - (dy / d) * lado * hh;
  const ey = (sy + hy) / 2 + (dx / d) * lado * hh;
  const w1 = 176 * g, w2 = 124 * g, w3 = 82 * g;
  const limb = (ax: number, ay: number, bx: number, by: number, wa: number, wb: number, off = 0) => {
    const ddx = bx - ax, ddy = by - ay, dd = Math.hypot(ddx, ddy) || 1;
    const px = -ddy / dd, py = ddx / dd;
    const mx = (ax + bx) / 2 + px * off, my = (ay + by) / 2 + py * off;
    const c = ((wa + wb) / 2) * 0.58;
    const o = (k: number) => [px * k, py * k];
    const [a1, a2] = o(wa / 2), [b1, b2] = o(wb / 2), [m1, m2] = o(c);
    return `M${f1(ax + a1 + px * off)} ${f1(ay + a2 + py * off)}Q${f1(mx + m1)} ${f1(my + m2)} ${f1(bx + b1 + px * off)} ${f1(by + b2 + py * off)}L${f1(bx - b1 + px * off)} ${f1(by - b2 + py * off)}Q${f1(mx - m1)} ${f1(my - m2)} ${f1(ax - a1 + px * off)} ${f1(ay - a2 + py * off)}Z`;
  };
  const ang = (Math.atan2(hy - ey, hx - ex) * 180) / Math.PI;
  const t = 0.36;
  const cx = ex + (hx - ex) * t, cy = ey + (hy - ey) * t;
  const wC = w2 + (w3 - w2) * t;
  const ux = (hx - ex) / Math.max(1, Math.hypot(hx - ex, hy - ey)), uy = (hy - ey) / Math.max(1, Math.hypot(hx - ex, hy - ey));
  const flat = PIEL[piel] || '#c58d64';
  const dark = '#00000030';
  const largos: [number, number][] = [[54, 40], [62, 44], [58, 42], [46, 34]];
  const ys = [-33, -11, 11, 33];
  const th = lado;
  return (
    <g>
      <path d={limb(ex, ey, hx, hy, w2, w3)} fill={`url(#${piel})`} />
      <path d={limb(ex, ey, hx, hy, w2 * 0.2, w3 * 0.2, -w3 * 0.26)} fill="#fff" opacity={0.16} />
      <path d={limb(sx, sy, ex, ey, w1, w2 * 1.04)} fill={`url(#${manga})`} />
      <path d={limb(sx, sy, ex, ey, w1 * 0.18, w2 * 0.18, -w2 * 0.28)} fill="#fff" opacity={0.15} />
      <path d={limb(ex, ey, cx, cy, w2 * 1.04, wC * 1.12)} fill={`url(#${manga})`} />
      <circle cx={ex} cy={ey} r={(w2 * 1.04) / 2} fill={`url(#${manga})`} />
      <path d={limb(cx - ux * 8, cy - uy * 8, cx + ux * 8, cy + uy * 8, wC * 1.2, wC * 1.2)} fill={dark} />
      <path d={`M${f1(ex - ux * 16)} ${f1(ey - uy * 16)}Q${f1(ex + ux * 30 + uy * 20 * th)} ${f1(ey + uy * 30 - ux * 20 * th)} ${f1(ex + ux * 70)} ${f1(ey + uy * 70)}`} stroke="#000" strokeOpacity={0.18} strokeWidth={6} fill="none" strokeLinecap="round" />
      <g transform={`translate(${f1(hx)} ${f1(hy)}) rotate(${f1(ang)}) scale(${g})`}>
        <path d="M-8 -42 Q40 -58 84 -50 L99 -36 L99 36 Q56 58 -8 42 Z" fill={`url(#${piel})`} />
        {ys.map((y, i) => {
          const a1 = curl * 30 * th, a2 = a1 + curl * 52 * th;
          const r1 = (a1 * Math.PI) / 180, r2 = (a2 * Math.PI) / 180;
          const x1 = 92 + largos[i][0] * Math.cos(r1), y1 = y + largos[i][0] * Math.sin(r1);
          const x2 = x1 + largos[i][1] * Math.cos(r2), y2 = y1 + largos[i][1] * Math.sin(r2);
          const pts = `92,${y} ${f1(x1)},${f1(y1)} ${f1(x2)},${f1(y2)}`;
          return (
            <g key={i}>
              <polyline points={pts} fill="none" stroke="#00000033" strokeWidth={30} strokeLinecap="round" strokeLinejoin="round" />
              <polyline points={pts} fill="none" stroke={flat} strokeWidth={25} strokeLinecap="round" strokeLinejoin="round" />
              <polyline points={`94,${y - 6} ${f1(x1)},${f1(y1 - 6)} ${f1(x2)},${f1(y2 - 6)}`} fill="none" stroke="#fff" strokeOpacity={0.22} strokeWidth={6} strokeLinecap="round" strokeLinejoin="round" />
              <ellipse cx={x2 + 4} cy={y2} rx={7} ry={9} fill="#fff" opacity={0.3} />
            </g>
          );
        })}
        <polyline points={`30,${-38 * th} 72,${-64 * th} 108,${-56 * th}`} fill="none" stroke="#00000033" strokeWidth={34} strokeLinecap="round" strokeLinejoin="round" />
        <polyline points={`30,${-38 * th} 72,${-64 * th} 108,${-56 * th}`} fill="none" stroke={flat} strokeWidth={29} strokeLinecap="round" strokeLinejoin="round" />
        <path d="M60 -44 Q80 -50 96 -38" stroke="#fff" strokeOpacity={0.22} strokeWidth={6} fill="none" strokeLinecap="round" />
      </g>
    </g>
  );
};

/* ---------- fondos ---------- */
const Pasillo: React.FC<{sem?: number}> = ({sem = 1}) => {
  const cols = ['#e9b9a6', '#a9d0e2', '#f3dd8c', '#b8dba5', '#d9b4e2', '#f4c99b', '#9dbfd7', '#ffffff'];
  const yo = (f: number) => 180 + f * 1320, yi = (f: number) => 560 + f * 520;
  const Y = (f: number, u: number) => yo(f) + (yi(f) - yo(f)) * u;
  const lado: React.ReactNode[] = [];
  for (let r = 0; r < 5; r++) for (let c = 0; c < 5; c++) {
    const f0 = r / 5 + 0.03, f1_ = (r + 0.8) / 5, x0 = c / 5, x1 = (c + 0.84) / 5;
    const col = cols[Math.floor(h(r * 7 + c + sem * 13) * cols.length)];
    lado.push(<polygon key={`${r}-${c}`} points={`${f1(x0 * 330)},${f1(Y(f0, x0))} ${f1(x1 * 330)},${f1(Y(f0, x1))} ${f1(x1 * 330)},${f1(Y(f1_, x1))} ${f1(x0 * 330)},${f1(Y(f1_, x0))}`} fill={col} opacity={0.9} />);
  }
  for (let r = 0; r <= 5; r++) lado.push(<line key={'b' + r} x1={0} y1={yo(r / 5)} x2={330} y2={yi(r / 5)} stroke="#8f9ca6" strokeWidth={10} />);
  return (
    <g>
      <rect x={-200} y={-200} width={1480} height={2600} fill="#e4eaee" />
      <polygon points="0,0 1080,0 1080,180 750,560 330,560 0,180" fill="#dfe6ea" />
      {[0, 1, 2].map((i) => <polygon key={i} points={`${380 + i * 90},${70 + i * 150} ${700 - i * 90},${70 + i * 150} ${690 - i * 85},${120 + i * 150} ${390 + i * 85},${120 + i * 150}`} fill="#fff" opacity={0.85} />)}
      <rect x={330} y={560} width={420} height={520} fill="#eef1f3" />
      {[0, 1, 2].map((i) => <rect key={i} x={360 + i * 130} y={600} width={100} height={46} rx={6} fill={cols[(i * 2 + sem) % 7]} opacity={0.9} />)}
      <polygon points="0,1500 330,1080 750,1080 1080,1500 1080,2400 0,2400" fill="url(#suelo)" />
      {[0, 1, 2].map((i) => <ellipse key={i} cx={540} cy={1150 + i * 150} rx={110 + i * 120} ry={14 + i * 8} fill="#fff" opacity={0.35} />)}
      <g>{lado}</g>
      <g transform="translate(1080 0) scale(-1 1)">{lado}</g>
    </g>
  );
};

