        {Array.from({length: 14}).map((_, i) => <line key={'a' + i} x1={170 + (i / 13) * 740} y1={1280} x2={150 + (i / 13) * 780} y2={1430} stroke="#c6d0d7" strokeWidth={4} opacity={0.8} />)}
        {Array.from({length: 17}).map((_, i) => <line key={'b' + i} x1={150 + (i / 16) * 780} y1={1430} x2={30 + (i / 16) * 1020} y2={1700} stroke="#d4dce1" strokeWidth={4} opacity={0.7} />)}
        {[0.3, 0.6].map((f, i) => <line key={'c' + i} x1={170 - f * 140} y1={1280 + f * 150} x2={910 + f * 20} y2={1280 + f * 150} stroke="#c6d0d7" strokeWidth={4} opacity={0.6} />)}
        <line x1={170} y1={1280} x2={910} y2={1280} stroke="#9aa7b1" strokeWidth={22} strokeLinecap="round" />
        <line x1={170} y1={1280} x2={30} y2={1700} stroke="#9aa7b1" strokeWidth={18} strokeLinecap="round" />
