      {[0.5].map((f) => <line key={f} x1={30 + f * 50} y1={1700 + f * 200} x2={1050 - f * 50} y2={1700 + f * 200} stroke="#cdd6dc" strokeWidth={5} opacity={0.9} />)}
      <line x1={30} y1={1700} x2={1050} y2={1700} stroke="#b4bfc7" strokeWidth={32} strokeLinecap="round" />
