const Cam: React.FC<{x: number; y: number; z: number; children: React.ReactNode}> = ({x, y, z, children}) => (
  <AbsoluteFill style={{transformOrigin: '0 0', transform: `translate(${f1(540 - x * z)}px,${f1(1000 - y * z)}px) scale(${z.toFixed(4)})`}}>{children}</AbsoluteFill>
);
const Lienzo: React.FC<{children: React.ReactNode}> = ({children}) => (
  <svg viewBox="0 0 1080 1920" width={1080} height={1920} style={{position: 'absolute', left: 0, top: 0, overflow: 'visible'}}><Defs />{children}</svg>
);
// posición de la mano que sostiene el frasco por su lado derecho
const manoFrasco = (jx: number, jy: number, e: number): [number, number] => [jx + 88 * e, jy + 25 * e];
const HS: [number, number] = [1250, 1700]; // hombro (fuera de cuadro) de la mano oscura

/* ================= E1 + E2: la mano, el carrito, el frasco que crece, la lupa ================= */
const EscA: React.FC = () => {
  const {s, spr} = useS();
  const tB = en('barato'), tAg = en('agarras'), tM = en('más', 2), tAh = en('ahorro'), tCasi = en('casi'), tUn = en('unidad'), tLand = en('siempre');
  const jx = 540 + Math.sin(s * 1.3) * 6;
  const jy = K(s, [[E[0], 800], [tLand, 1405], [tAg, 1405], [tAg + 0.85, 1010], [E[2], 1010]]);
  const e = K(s, [[E[0], 1.7], [tLand, 1.25], [tAg, 1.25], [tAg + 0.85, 1.7], [tM, 1.7], [tM + 0.5, 2.4], [tM + 0.8, 2.25], [tAh, 2.3], [tAh + 0.5, 2.7], [E[2], 2.7]]);
  const sq = golpe(s, tLand, 24, 8) * 0.08 + golpe(s, tM, 16, 6) * 0.06 + golpe(s, tM + 0.8, 16, 6) * 0.03;
  const r = K(s, [[tLand + 0.1, 0], [tLand + 0.8, 1], [tAg - 0.5, 1], [tAg, 0]]);
  const [ax, ay] = manoFrasco(jx, jy, e);
  const hx = ax * (1 - r) + 850 * r, hy = ay * (1 - r) + 1430 * r;
  const curlA = 0.55 - 0.45 * K(s, [[tLand + 0.1, 0], [tLand + 0.6, 1], [tAg - 0.5, 1], [tAg - 0.1, 0]]);
  const grieta = K(s, [[tB - 0.05, 0], [tB + 0.15, 1]]);
  const un = K(s, [[tUn - 0.05, 0], [tUn + 0.2, 1]]);
  const lupaX = K(s, [[tCasi - 0.1, -300], [tCasi + 1.5, 1400]], Easing.inOut(Easing.sin));
  const lupaY = K(s, [[tCasi - 0.1, jy - 150], [tCasi + 1.5, jy + 70]], Easing.inOut(Easing.sin));
  const monedaT = s - tAh;
  const camZ = K(s, [[E[0], 1.0], [tLand + 0.2, 1.12], [tB, 1.3], [E[1], 1.3], [tAg + 0.6, 1.0], [tM + 0.4, 0.98], [tUn - 0.3, 0.98], [tUn + 0.2, 1.5], [E[2], 1.5]]);
