/* ================= balanza con su par de frascos (E4 y E5) ================= */
const Par: React.FC<{cx: number; cy: number; k?: number; ang: number; rojo?: number; oro?: number; aro?: number; flecha?: number; gris?: number; pulso?: number; w?: number; kgG?: string; kgP?: string}> = ({cx, cy, k = 1, ang, rojo = 0, oro = 0, aro = 0, flecha = 0, gris = 0, pulso = 0, w = 0, kgG = '', kgP = ''}) => {
  const r = (ang * Math.PI) / 180;
  const lx = -150 * Math.cos(r), ly = -150 * Math.sin(r), rx = 150 * Math.cos(r), ry = 150 * Math.sin(r);
  const eG = 0.8 * (1 + pulso * 0.15), eP = 0.52 * (1 + pulso * 0.15);
  const pan = (ex: number, ey: number) => (
    <g>
      <line x1={ex} y1={ey} x2={ex - 90} y2={ey + 170} stroke="#7b8791" strokeWidth={4} />
      <line x1={ex} y1={ey} x2={ex + 90} y2={ey + 170} stroke="#7b8791" strokeWidth={4} />
      <path d={`M${f1(ex - 105)} ${f1(ey + 170)}Q${f1(ex)} ${f1(ey + 222)} ${f1(ex + 105)} ${f1(ey + 170)}Z`} fill="url(#metal)" stroke="#6f7b84" strokeWidth={3} />
      <ellipse cx={ex} cy={ey + 170} rx={105} ry={11} fill="#cfd8de" stroke="#6f7b84" strokeWidth={3} />
    </g>
  );
  return (
    <g transform={`translate(${f1(cx)} ${f1(cy)}) scale(${k})`}>
      <ellipse cx={0} cy={330} rx={150} ry={22} fill="#000" opacity={0.16} />
      <path d="M-110 332Q0 262 110 332Z" fill="url(#metal)" stroke="#6f7b84" strokeWidth={3} />
      <rect x={-12} y={0} width={24} height={300} rx={10} fill="url(#metal)" />
      {aro > 0 && <ellipse cx={0} cy={130} rx={330} ry={360} fill="none" stroke={ORO} strokeWidth={9} opacity={aro} />}
      {pan(lx, ly)}{pan(rx, ry)}
      <Frasco x={lx} y={ly + 170 - 140 * eG} e={eG} rojo={rojo} gris={gris} kg={kgG} />
      <Frasco x={rx} y={ry + 170 - 140 * eP} e={eP} oro={oro} kg={kgP} />
      <g transform={`rotate(${f1(ang)})`}>
        <rect x={-165} y={-10} width={330} height={20} rx={10} fill="url(#metal)" stroke="#6f7b84" strokeWidth={3} />
        <circle cx={-150} cy={0} r={9} fill="#6f7b84" /><circle cx={150} cy={0} r={9} fill="#6f7b84" />
      </g>
      <circle r={20} fill="#8a959e" stroke="#58636b" strokeWidth={4} />
      {flecha > 0 && (
        <g transform={`translate(${f1(lx)} ${f1(ly - 150 - Math.sin(w * 6) * 8)}) scale(${flecha})`}>
          <polygon points="0,-46 40,6 14,6 14,50 -14,50 -14,6 -40,6" fill={ROJO} stroke="#fff" strokeWidth={5} />
        </g>
      )}
    </g>
  );
};

