          antes={<EscB />}
          despues={<Paso t={E[5]} tipo="entrar" x={810} y={1000}
            antes={<CD />}
            despues={s < E[7] ? <EscF /> : <EscG />} />} />} />
      <AbsoluteFill style={{background: 'linear-gradient(180deg,rgba(12,20,30,.62) 0,rgba(12,20,30,0) 26%)'}} />
      <AbsoluteFill style={{boxShadow: `inset 0 0 260px 30px ${col}`, opacity: 0.5}} />
    </AbsoluteFill>
  );
};

